package com.aliothmoon.maafw.once;
import org.junit.Test;import static org.junit.Assert.*;import java.nio.file.*;
/** Wiring only; actual same-frame/actor/resource proof is exercised by pipeline fixtures. */
public class RootSelectedPendingWiringTest {
 private String src(String n)throws Exception{return Files.readString(Path.of(System.getProperty("staging.root",".."),"app/src/main/java/com/aliothmoon/maafw/once",n)).replace("\r\n","\n");}
 private String section(String s,String a,String b){int n=s.indexOf(a);assertTrue(a,n>=0);int e=s.indexOf(b,n);assertTrue(b,e>n);return s.substring(n,e);}
 @Test public void newNamespaceIsIndependentAndBounded(){assertNotEquals(RootSelectedPendingScope.DIRECTORY,RootBoundedBusinessScope.DIRECTORY);assertEquals(3,RootSelectedPendingScope.MAX_PER_PHASE);assertEquals(6,RootSelectedPendingScope.MAX_FRAMES);assertEquals(180000,RootSelectedPendingScope.SESSION_TTL);assertEquals(90000,RootSelectedPendingScope.CAPTURE_TTL);assertEquals(15,RootSelectedPendingScope.SOURCE_TASK_ID);}
 @Test public void immutableModeCannotBindLegacyRun()throws Exception{String s=src("RootBoundedBusinessIntent.java");assertTrue(s.contains("final boolean live,selectedPending"));assertTrue(s.contains("exact.selectedPendingOnly()!=selectedPending"));assertTrue(s.contains("RootSelectedPendingScope.current"));assertTrue(s.contains("RootSelectedPendingScope.SOURCE_TASK_ID"));}
 @Test public void issuerIsNewAndOldLiveEntriesAreExplicitlyDisabled()throws Exception{String s=src("VisibleCaptureAuthority.java");assertTrue(s.contains("issueSelectedPendingIntent("));assertTrue(s.contains("issueSelectedPendingFrame("));assertTrue(s.contains("selectedPendingApprovalMatches"));assertTrue(s.contains("RootSelectedPendingScope.sessionDeadline"));assertEquals(16,s.split("Selected B live issuer only",-1).length-1);assertTrue(s.contains("Nonlive legacy bounded fixture only"));}
 @Test public void positiveCannotBeReadonlyCastAndHoldKeepsEvidence()throws Exception{String s=src("CaptureSessionRuntime.java");String d=section(s,"static BoundedCompletion.Disposition boundedDisposition(","private void closeBoundedOnOwner()");assertTrue(d.contains("observation.selectedPendingOnly()"));assertTrue(d.contains("observation.selectedProofReady()"));assertTrue(d.contains("explicitUnpresented(observation,audit,markers)"));assertFalse(d.contains("currentCards()"));assertTrue(s.contains("preparedObservation.selectedEvidenceSummary()"));assertTrue(s.contains("o.selectedPendingOnly()!=intent.selectedPending()"));}
 @Test public void runtimeUsesFreshSelectedClaimsAndNoNewFrameLoop()throws Exception{String s=src("CaptureSessionRuntime.java");assertTrue(s.contains("VisibleCaptureAuthority.issueSelectedPendingFrame("));assertTrue(s.contains("RootSelectedPendingScope.store("));assertTrue(s.contains("business.selectedPendingOnly()!=intent.selectedPending()"));assertTrue(s.contains("RootSelectedPendingScope.ACTIVE"));assertTrue(s.contains("SELECTED_PENDING_B_V35"));}
 @Test public void navigationUsesOriginalAnchorAndOriginalTwelvePairs()throws Exception{String r=src("ReviewBingNavigation.java");assertTrue(r.contains("readSelected("));assertTrue(r.contains("parseSelectedNavigation("));assertTrue(r.contains("PAIRS.incrementAndGet()>12"));String c=src("NativeBingReturnController.java");assertTrue(c.contains("ORIGINAL_SOURCE_ALREADY_READY"));assertTrue(c.contains("for(int i=0;i<3;i++)"));assertTrue(c.contains("for(int i=0;i<2;i++)"));assertTrue(c.contains("navigationFirstGate="));assertTrue(c.contains("ports.metadataClean()"));}
 @Test public void crossParserNeverRewritesEvidenceOrEmitsReady()throws Exception{String s=src("BingNavigationSnapshot.java");String p=section(s,"static Result parseSelectedNavigation(","private static boolean cross");assertFalse(p.contains(".replace("));assertFalse(p.contains("new Ready("));assertTrue(p.contains("SELECTED_BOUND_CROSS_ACTIVITY"));assertTrue(p.contains("SELECTED_CROSS_UNPROVEN"));}
 @Test public void selectedDisclosureHasOnlyBAndSeparateRosterMeaning()throws Exception{String s=src("RootCaptureUi.java");assertTrue(s.contains("Test your knowledge on these topics"));assertTrue(s.contains("03:00"));assertTrue(s.contains("05:00"));assertTrue(s.contains("selectedPendingChoice("));String a=src("DormantCaptureConfirmationActivity.java");assertTrue(a.contains("confirmedSelectedPending("));assertTrue(a.contains("startSelectedPending("));assertTrue(a.contains("selectedPendingApprovalMatches("));}
}
